fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    // Since 0 < n < list.len() and list is non-empty,
    // we can safely split using slicing.
    
    let len = list.len();
    let mut new_list = Vec::with_capacity(len);

    // Append elements from index n to the end
    new_list.extend_from_slice(&list[n..]);

    // Append elements from start up to n (exclusive)
    new_list.extend_from_slice(&list[0..n]);

    new_list
}